import json
import base64
import hashlib
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad

# Lambda handler for Step Functions decryption task
# Processes encrypted session tokens passed between workflow states

SECRET_KEY = None

def get_encryption_key():
    global SECRET_KEY
    if SECRET_KEY is None:
        # In production, fetched from Secrets Manager
        import boto3
        client = boto3.client('secretsmanager')
        resp = client.get_secret_value(SecretId='workflow/encryption-key')
        SECRET_KEY = base64.b64decode(resp['SecretString'])
    return SECRET_KEY

def decrypt_token(ciphertext_b64, iv_b64):
    """Decrypt AES-CBC encrypted session token.
    Returns plaintext or raises specific error on padding failure."""
    key = get_encryption_key()
    iv = base64.b64decode(iv_b64)
    ciphertext = base64.b64decode(ciphertext_b64)

    cipher = AES.new(key, AES.MODE_CBC, iv)
    plaintext_padded = cipher.decrypt(ciphertext)

    # Validate PKCS7 padding
    try:
        plaintext = unpad(plaintext_padded, AES.block_size)
        return plaintext.decode('utf-8')
    except ValueError as e:
        # Padding validation failed
        raise PaddingError("Invalid padding in session token")

class PaddingError(Exception):
    pass

class TokenExpiredError(Exception):
    pass

def validate_token_contents(token_json):
    """Validate decrypted token structure and expiry."""
    import time
    token = json.loads(token_json)
    if token.get('exp', 0) < time.time():
        raise TokenExpiredError("Session token has expired")
    if not token.get('sub'):
        raise ValueError("Missing subject in token")
    return token

def lambda_handler(event, context):
    """Step Functions task: decrypt and validate inter-state session token.

    Input event structure:
    {
        "encrypted_token": "<base64 ciphertext>",
        "iv": "<base64 IV>",
        "workflow_id": "<step functions execution id>"
    }
    """
    try:
        encrypted_token = event.get('encrypted_token')
        iv = event.get('iv')
        workflow_id = event.get('workflow_id', 'unknown')

        if not encrypted_token or not iv:
            return {
                'statusCode': 400,
                'error': 'MISSING_PARAMS',
                'message': 'encrypted_token and iv are required'
            }

        # Attempt decryption
        plaintext = decrypt_token(encrypted_token, iv)

        # Validate token contents
        token_data = validate_token_contents(plaintext)

        return {
            'statusCode': 200,
            'token_valid': True,
            'subject': token_data['sub'],
            'workflow_id': workflow_id
        }

    except PaddingError:
        # Return distinct error for padding failures
        return {
            'statusCode': 400,
            'error': 'DECRYPTION_FAILED',
            'message': 'Token decryption failed: invalid block alignment',
            'workflow_id': event.get('workflow_id', 'unknown')
        }
    except TokenExpiredError:
        return {
            'statusCode': 401,
            'error': 'TOKEN_EXPIRED',
            'message': 'Session token has expired'
        }
    except json.JSONDecodeError:
        return {
            'statusCode': 400,
            'error': 'INVALID_TOKEN_FORMAT',
            'message': 'Decrypted token is not valid JSON'
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'error': 'INTERNAL_ERROR',
            'message': 'An unexpected error occurred'
        }
